void arenaPlayWeapon(int);
namespace arena{
const float PI=3.14159265358979323846f;
inline float clamp(float x,float a,float b){return std::max(a,std::min(b,x));}
struct V3{float x,y,z;V3(float X=0,float Y=0,float Z=0):x(X),y(Y),z(Z){}V3 operator+(V3 b)const{return V3(x+b.x,y+b.y,z+b.z);}V3 operator-(V3 b)const{return V3(x-b.x,y-b.y,z-b.z);}V3 operator*(float s)const{return V3(x*s,y*s,z*s);}};
inline float dot(V3 a,V3 b){return a.x*b.x+a.y*b.y+a.z*b.z;}inline float length(V3 a){return std::sqrt(dot(a,a));}inline V3 normalized(V3 a){float n=length(a);return n>.00001f?a*(1/n):V3(0,0,-1);}
inline bool rayBox(V3 p,V3 d,V3 lo,V3 hi,float&out){float enter=0,exit=10000,o[]={p.x,p.y,p.z},v[]={d.x,d.y,d.z},a[]={lo.x,lo.y,lo.z},b[]={hi.x,hi.y,hi.z};for(int i=0;i<3;i++){if(std::fabs(v[i])<.000001f){if(o[i]<a[i]||o[i]>b[i])return false;}else{float t1=(a[i]-o[i])/v[i],t2=(b[i]-o[i])/v[i];if(t1>t2)std::swap(t1,t2);enter=std::max(enter,t1);exit=std::min(exit,t2);if(enter>exit)return false;}}out=enter;return exit>=0;}
inline bool raySphere(V3 p,V3 d,V3 c,float r,float&out){V3 m=p-c;float b=dot(m,d),disc=b*b-dot(m,m)+r*r;if(disc<0)return false;float t=-b-std::sqrt(disc);if(t<0)t=-b+std::sqrt(disc);if(t<0)return false;out=t;return true;}
struct WeaponDef{const char*name;int mag,stock,pellets;float damage,head,interval,reload,spread,range;};
inline const WeaponDef&weaponDef(int id){static const WeaponDef w[10]={
{"PISTOLA",12,84,1,35,90,.28f,1.2f,.004f,40},{"REVOLVER",6,48,1,65,140,.55f,1.8f,.003f,45},{"SMG",30,180,1,20,45,.075f,1.45f,.022f,32},{"FUZIL",30,150,1,25,75,.115f,1.5f,.009f,45},{"AK",30,150,1,34,90,.14f,1.8f,.014f,45},{"ESCOPETA",8,48,8,13,22,.8f,2.1f,.095f,22},{"SNIPER",5,35,1,100,220,1.15f,2.4f,.001f,60},{"METRALHA",80,240,1,24,60,.09f,3.2f,.025f,45},{"CARABINA",20,120,1,42,105,.24f,1.65f,.004f,50},{"DUPLA",2,40,12,14,24,.55f,1.9f,.12f,18}};return w[id<0?0:(id>9?9:id)];}
struct Map{
 static const int W=21;int cell[W*W],distance[W*W];Map(){build(0);}
 void build(int level){for(int z=0;z<W;z++)for(int x=0;x<W;x++)cell[z*W+x]=(x==0||z==0||x==W-1||z==W-1);const LevelDef&d=levelDef(level);for(int k=0;k<d.count;k++){const Block&b=d.blocks[k];for(int z=b.z0;z<=b.z1;z++)for(int x=b.x0;x<=b.x1;x++)cell[z*W+x]=1;}for(int i=0;i<W*W;i++)distance[i]=9999;}
 bool solid(int x,int z)const{return x<0||z<0||x>=W||z>=W||cell[z*W+x]!=0;}
 bool blocked(float x,float z,float r)const{int ix=int(std::floor(x)),iz=int(std::floor(z));for(int a=ix-1;a<=ix+1;a++)for(int b=iz-1;b<=iz+1;b++)if(solid(a,b)){float dx=x-clamp(x,float(a),float(a+1)),dz=z-clamp(z,float(b),float(b+1));if(dx*dx+dz*dz<r*r)return true;}return false;}
 void move(float&x,float&z,float dx,float dz,float r)const{if(!blocked(x+dx,z,r))x+=dx;if(!blocked(x,z+dz,r))z+=dz;}
 float ray(V3 p,V3 d,float far=50)const{float best=far;for(int z=0;z<W;z++)for(int x=0;x<W;x++)if(cell[z*W+x]){float t;if(rayBox(p,d,V3(x,0,z),V3(x+1,2.8f,z+1),t)&&t<best)best=t;}if(d.y<-.00001f){float t=-p.y/d.y;if(t>=0&&t<best)best=t;}if(d.y>.00001f){float t=(2.8f-p.y)/d.y;if(t>=0&&t<best)best=t;}return best;}
 bool visible(float x,float z,float tx,float tz)const{V3 p(x,1.55f,z),v(tx-x,0,tz-z);float len=length(v);return len<.01f||ray(p,v*(1/len),len)>=len-.05f;}
 void rebuildPaths(float px,float pz){for(int i=0;i<W*W;i++)distance[i]=9999;int x=int(px),z=int(pz);if(solid(x,z))return;std::queue<int>q;distance[z*W+x]=0;q.push(z*W+x);const int dx[]={1,-1,0,0},dz[]={0,0,1,-1};while(!q.empty()){int p=q.front();q.pop();for(int k=0;k<4;k++){int nx=p%W+dx[k],nz=p/W+dz[k];if(!solid(nx,nz)&&distance[nz*W+nx]>distance[p]+1){distance[nz*W+nx]=distance[p]+1;q.push(nz*W+nx);}}}}
 V3 stepToward(float x,float z,float px,float pz)const{int cx=int(x),cz=int(z);if(solid(cx,cz))return V3(px,0,pz);int index=cz*W+cx,best=distance[index];V3 target(cx+.5f,0,cz+.5f);const int dx[]={1,-1,0,0},dz[]={0,0,1,-1};for(int k=0;k<4;k++){int nx=cx+dx[k],nz=cz+dz[k];if(!solid(nx,nz)&&distance[nz*W+nx]<best){best=distance[nz*W+nx];target=V3(nx+.5f,0,nz+.5f);}}if(distance[index]==0)target=V3(px,0,pz);return target;}
};
struct Bot{float x,z,oldX,oldZ,hp,angle,fireTimer,visionTimer,flash,death,phase,gait,speed,walkX,walkZ,alert,lastSeenX,lastSeenZ,memory;bool sees;Bot(float X,float Z,float P):x(X),z(Z),oldX(X),oldZ(Z),hp(70),angle(0),fireTimer(1.5f+P*.08f),visionTimer(0),flash(0),death(0),phase(P),gait(P),speed(0),walkX(0),walkZ(1),alert(0),lastSeenX(X),lastSeenZ(Z),memory(0),sees(false){}};
struct Trace{V3 a,b;float time;bool hostile;Trace(V3 A,V3 B,bool h):a(A),b(B),time(.075f),hostile(h){}};
enum Mode{MENU,SETTINGS,LEVELSELECT,PLAY,PAUSED,DEAD,VICTORY};
struct Game{
 Map map;Mode mode;float x,z,oldX,oldZ,yaw,pitch,moveX,moveY,hp,reload,fireTimer,recoil,hurt,hitMarker,killMarker,time,pathTimer,nextWave;int level,wave,kills,score,selected[2],editing,active,ammo[2],reserve[2];bool fireHeld,terror;uint32_t rng;std::vector<Bot>bots;std::vector<Trace>traces;
 Game():mode(MENU),level(0),terror(true),rng(0x7A31F02u){selected[0]=3;selected[1]=0;editing=0;reset();}const WeaponDef&gun()const{return weaponDef(selected[active]);}
 float random(){rng^=rng<<13;rng^=rng>>17;rng^=rng<<5;return (rng&0xffffff)/16777216.f;}void stopControls(){moveX=moveY=0;fireHeld=false;}
 void reset(){map.build(level);const LevelDef&d=levelDef(level);x=d.spawnX;z=d.spawnZ;oldX=x;oldZ=z;yaw=pitch=0;hp=100;reload=fireTimer=recoil=hurt=hitMarker=killMarker=time=pathTimer=nextWave=0;wave=1;kills=score=0;active=0;for(int i=0;i<2;i++){ammo[i]=weaponDef(selected[i]).mag;reserve[i]=weaponDef(selected[i]).stock;}stopControls();bots.clear();traces.clear();}
 void choose(int id){if(id<0||id>=10)return;if(id==selected[1-editing])std::swap(selected[0],selected[1]);else selected[editing]=id;}
 void start(){reset();mode=PLAY;map.rebuildPaths(x,z);spawnWave();}void switchWeapon(){if(mode!=PLAY)return;active=1-active;reload=0;fireTimer=.3f;recoil=0;}
 int alive()const{int n=0;for(size_t i=0;i<bots.size();i++)if(bots[i].hp>0)n++;return n;}
 void spawnWave(){bots.clear();int count=terror?std::min(4,2+wave):std::min(8,3+wave);for(int i=0;i<count;i++){bool found=false;for(int pass=0;pass<2&&!found;pass++)for(int tries=0;tries<600;tries++){float sx=1.5f+int(random()*18),sz=1.5f+int(random()*18);if(map.blocked(sx,sz,.3f)||map.distance[int(sz)*Map::W+int(sx)]>=9999)continue;float dx=sx-x,dz=sz-z;if(dx*dx+dz*dz<36)continue;bool close=false;for(size_t b=0;b<bots.size();b++){float a=sx-bots[b].x,c=sz-bots[b].z;if(a*a+c*c<2)close=true;}if(close||(pass==0&&map.visible(sx,sz,x,z)))continue;bots.push_back(Bot(sx,sz,float(i)));if(terror)bots.back().hp=125;found=true;break;}}}
 void beginReload(){if(mode==PLAY&&reload<=0&&ammo[active]<gun().mag&&reserve[active]>0)reload=gun().reload;}
 V3 direction()const{return V3(std::sin(yaw)*std::cos(pitch),std::sin(pitch),-std::cos(yaw)*std::cos(pitch));}
 void shoot(){if(reload>0||fireTimer>0)return;if(ammo[active]<=0){beginReload();return;}const WeaponDef&w=gun();--ammo[active];fireTimer=w.interval;recoil=1;arenaPlayWeapon(selected[active]);if(terror)for(size_t i=0;i<bots.size();i++)if(bots[i].hp>0){bots[i].alert=12;float noise=(w.pellets>1?9.f:6.f)*(1.f-clamp(length(V3(bots[i].x-x,0,bots[i].z-z))/40.f,.25f,1.f));bots[i].lastSeenX=x+(random()-.5f)*noise;bots[i].lastSeenZ=z+(random()-.5f)*noise;bots[i].memory=6.f;}V3 origin(x,1.62f,z),forward=direction(),right(std::cos(yaw),0,std::sin(yaw)),up(-std::sin(yaw)*std::sin(pitch),std::cos(pitch),std::cos(yaw)*std::sin(pitch));for(int pellet=0;pellet<w.pellets;pellet++){float a=random()*2*PI,r=std::sqrt(random())*w.spread;V3 d=normalized(forward+right*(std::cos(a)*r)+up*(std::sin(a)*r));float best=map.ray(origin,d,w.range);int victim=-1;bool head=false;for(size_t i=0;i<bots.size();i++){Bot&b=bots[i];if(b.hp<=0)continue;float t;if(raySphere(origin,d,V3(b.x,1.65f,b.z),.25f,t)&&t<best){best=t;victim=int(i);head=true;}if(rayBox(origin,d,V3(b.x-.29f,.15f,b.z-.24f),V3(b.x+.29f,1.4f,b.z+.24f),t)&&t<best){best=t;victim=int(i);head=false;}}traces.push_back(Trace(origin+right*.22f+V3(0,-.17f,0)+forward*.35f,origin+d*best,false));if(victim>=0){Bot&b=bots[victim];b.hp-=head?w.head:w.damage;b.flash=.12f;hitMarker=.13f;b.alert=12;b.lastSeenX=x;b.lastSeenZ=z;b.memory=6.f;if(b.hp<=0){kills++;score+=head?150:100;killMarker=.18f;b.death=1.1f;}}}if(ammo[active]==0)beginReload();}
 void update(float dt){if(mode!=PLAY||dt<=0)return;time+=dt;oldX=x;oldZ=z;fireTimer=std::max(0.f,fireTimer-dt);recoil=std::max(0.f,recoil-dt*8);hurt=std::max(0.f,hurt-dt);hitMarker=std::max(0.f,hitMarker-dt);killMarker=std::max(0.f,killMarker-dt);if(reload>0){reload-=dt;if(reload<=0){reload=0;int n=std::min(gun().mag-ammo[active],reserve[active]);ammo[active]+=n;reserve[active]-=n;}}float mx=moveX,my=moveY,mag=std::sqrt(mx*mx+my*my);if(mag>1){mx/=mag;my/=mag;}map.move(x,z,(std::cos(yaw)*mx+std::sin(yaw)*my)*3.5f*dt,(std::sin(yaw)*mx-std::cos(yaw)*my)*3.5f*dt,.23f);pathTimer-=dt;if(pathTimer<=0){map.rebuildPaths(x,z);pathTimer=.22f;}if(fireHeld)shoot();for(size_t i=0;i<traces.size();){traces[i].time-=dt;if(traces[i].time<=0)traces.erase(traces.begin()+i);else i++;}
 for(size_t i=0;i<bots.size();i++){Bot&b=bots[i];b.oldX=b.x;b.oldZ=b.z;b.flash=std::max(0.f,b.flash-dt);if(b.hp<=0){b.death=std::max(0.f,b.death-dt);continue;}float vx=x-b.x,vz=z-b.z,dist=std::max(.01f,std::sqrt(vx*vx+vz*vz));b.visionTimer-=dt;b.fireTimer-=dt;b.alert=std::max(0.f,b.alert-dt);if(b.memory>0)b.memory-=dt;if(b.visionTimer<=0){b.sees=dist<(terror?14:18)&&map.visible(b.x,b.z,x,z);b.visionTimer=.12f;}if(b.sees){b.lastSeenX=x;b.lastSeenZ=z;b.memory=terror?5.f:3.5f;}if(terror&&b.sees)b.alert=6;if(terror&&dist<5&&(std::fabs(moveX)+std::fabs(moveY))>.15f){b.alert=std::max(b.alert,2.f);b.lastSeenX=x;b.lastSeenZ=z;b.memory=std::max(b.memory,2.5f);}float bx=0,bz=0;
 if(terror&&b.alert<=0&&b.memory<=0&&!b.sees){bx=std::sin(time*.23f+b.phase*2.7f)*.4f;bz=std::cos(time*.19f+b.phase*1.4f)*.4f;}else if(terror&&b.sees){if(dist>.86f){bx=vx/dist;bz=vz/dist;}}else if(terror&&b.memory>0){float sx=b.lastSeenX-b.x,sz=b.lastSeenZ-b.z,n=std::sqrt(sx*sx+sz*sz);if(n>.55f){bx=sx/n;bz=sz/n;}else b.memory=0;}else if(!terror&&b.sees&&dist<11){float ap=dist>7?1.f:(dist<4?-1.f:0.f),side=std::sin(time*.85f+b.phase*2)*.55f;bx=vx/dist*ap-vz/dist*side;bz=vz/dist*ap+vx/dist*side;}else if(!terror&&b.memory>0){V3 t=map.stepToward(b.x,b.z,b.lastSeenX,b.lastSeenZ);bx=t.x-b.x;bz=t.z-b.z;float n=std::sqrt(bx*bx+bz*bz);if(n>.02f){bx/=n;bz/=n;}else b.memory=0;}else{V3 t=map.stepToward(b.x,b.z,x,z);bx=t.x-b.x;bz=t.z-b.z;float n=std::sqrt(bx*bx+bz*bz);if(n>.02f){bx/=n;bz/=n;}else bx=bz=0;}
 for(size_t j=0;j<bots.size();j++){if(j==i)continue;const Bot&o=bots[j];if(o.hp<=0)continue;float sx=b.x-o.x,sz=b.z-o.z,d2=sx*sx+sz*sz;if(d2<.81f&&d2>.0001f){float d=std::sqrt(d2),push=(.9f-d)*1.7f;bx+=sx/d*push;bz+=sz/d*push;}}
 float desired=terror&&b.alert<=0&&b.memory<=0&&!b.sees?std::atan2(bx,bz):(b.sees||b.memory>0?std::atan2((b.sees?vx:(b.lastSeenX-b.x)),(b.sees?vz:(b.lastSeenZ-b.z))):std::atan2(vx,vz));float turn=std::atan2(std::sin(desired-b.angle),std::cos(desired-b.angle));b.angle+=turn*std::min(1.f,dt*(terror?4.f:7.f));float speed=terror?(b.alert>0||b.memory>0?1.48f+int(b.phase)%3*.14f+wave*.05f:.70f):(1.12f+std::min(wave,12)*.055f);if(terror&&b.alert<=0&&b.memory<=0&&std::fmod(time+b.phase*3.1f,13.f)<2.2f)speed=0;map.move(b.x,b.z,bx*speed*dt,bz*speed*dt,.27f);float movedX=b.x-b.oldX,movedZ=b.z-b.oldZ,moved=std::sqrt(movedX*movedX+movedZ*movedZ);b.speed+=(moved/dt-b.speed)*std::min(1.f,dt*10);b.gait=std::fmod(b.gait+moved*2*PI,2*PI);if(moved>.00001f){float wx=(movedX*std::cos(b.angle)-movedZ*std::sin(b.angle))/moved,wz=(movedX*std::sin(b.angle)+movedZ*std::cos(b.angle))/moved;b.walkX+=(wx-b.walkX)*std::min(1.f,dt*12);b.walkZ+=(wz-b.walkZ)*std::min(1.f,dt*12);}
 if(terror){float ax=x-b.x,az=z-b.z;if(ax*ax+az*az<1.15f*1.15f&&b.fireTimer<=0&&map.visible(b.x,b.z,x,z)){b.fireTimer=1.15f+random()*.25f;hp=std::max(0.f,hp-(int(b.phase)%3==1?17:13));hurt=.30f;}}else if(b.sees&&b.fireTimer<=0&&map.visible(b.x,b.z,x,z)){b.fireTimer=1.05f+random()*.7f-std::min(wave,8)*.035f;bool hit=random()<clamp(.8f-dist*.035f,.18f,.75f);traces.push_back(Trace(V3(b.x,1.3f,b.z),V3(x+(hit?0:1+random()),1.3f,z),true));if(hit){hp=std::max(0.f,hp-7);hurt=.22f;}}if(hp<=0){mode=DEAD;stopControls();break;}}
 if(mode==PLAY&&alive()==0){if(wave>=3){mode=VICTORY;stopControls();return;}if(nextWave<=0)nextWave=3;else{nextWave-=dt;if(nextWave<=0){wave++;hp=std::min(100.f,hp+15);for(int i=0;i<2;i++){const WeaponDef&w=weaponDef(selected[i]);reserve[i]=std::min(w.stock*2,reserve[i]+w.mag*2);}spawnWave();nextWave=0;}}}}
};}
#endif
